package com.smartspend.controller;
import com.smartspend.model.User;import com.smartspend.dao.UserDAO;import com.smartspend.util.*;import javafx.geometry.*;import javafx.scene.control.*;import javafx.scene.layout.*;import javafx.stage.Stage;
public class SettingsView extends VBox {public SettingsView(Stage stage){setPadding(new Insets(5,30,30,30));setSpacing(15);User u=Session.getUser();TextField name=UI.input("Full name");name.setText(u.getName());TextField email=UI.input("Email");email.setText(u.getEmail());ComboBox<String>currency=new ComboBox<>();currency.getItems().addAll("INR ₹","USD $","EUR €");currency.setValue("INR ₹");ComboBox<String>theme=new ComboBox<>();theme.getItems().addAll("Dark","System");theme.setValue("Dark");CheckBox notifications=new CheckBox("Enable notifications");notifications.setSelected(true);Button save=UI.button("Save Preferences");save.setOnAction(e->{try{if(name.getText().isBlank()||!ValidationUtil.email(email.getText()))throw new IllegalArgumentException("Enter a valid name and email.");new UserDAO().updateProfile(u.getId(),name.getText().trim(),email.getText().trim().toLowerCase());u.setName(name.getText().trim());u.setEmail(email.getText().trim().toLowerCase());UI.alert(stage,"Saved","Profile and preferences saved successfully.");}catch(Exception ex){UI.error(stage,ex.getMessage());}});getChildren().addAll(UI.title("Settings"),UI.subtitle("Profile, currency and notification preferences."),UI.card(new Label("Profile"),name,email,save),UI.card(new Label("Preferences"),currency,theme,notifications),UI.card(new Label("Security"),new Label("Passwords are stored as PBKDF2WithHmacSHA256 hashes. Database credentials are read from environment variables.")));}}
